const RT_ANOM=["A {p} c'è una cosa nuova. Una luce bassa, ferma, color latte. Non l'ho mai vista. Non mi sono avvicinato.","Passando da {p} ho sentito cantare. Nessuno canta a {p}. Nessuno vivo.","A {p} gli alberi sono piegati tutti verso un punto. Ieri non lo erano.","Qualcuno sa cos'è la nebbia viola a {p}? Il contatore taceva. Il cane abbaiava."];
const RT_SOGNO=["Stanotte ho sognato un uomo con la faccia di vetro che mi chiedeva l'ora. Gliel'ho detta. Si è messo a piangere.","Ho sognato di camminare sul fondo del lago di Yantar. C'erano case. Con le luci accese.","Sogno sempre la stessa frase: «la quarta porta è aperta». Non so che porta. Non so quale quarta.","Ho sognato tutti voi, seduti a un tavolo lungo, a mangiare in silenzio. Mancava qualcuno. Mi sono svegliato prima di capire chi."];
const RT_CONF=["Confessione anonima. Ho lasciato indietro un uomo, la settimana scorsa. Era ferito. Sentivo i cani. Non chiedetemi il nome. Chiedetemi solo se si può vivere con questo.","Confessione anonima. Ho rubato al Bar. Non tanto. Ma il Barman mi guarda in un modo, da allora.","Confessione anonima. Ho venduto ai banditi la strada di una squadra di novellini. Due sono morti. Pagavano bene. Non dormo più.","Confessione anonima. Non sono mai entrato in un campo di anomalie. Tutto quello che ho raccontato al fuoco l'ho sentito da altri. Ma la gente mi ascolta."];
const RT_PRED=["Fratelli. Il Monolite vi chiama. Non è una minaccia. È un invito. Il centro della Zona esaudisce un desiderio a chi arriva puro. Siete puri?","Il Bruciacervelli taceva per proteggerci. Ora che è spento, la Voce parla a chi sa ascoltare. Io ascolto. Venite.","Voi contate i rubli. Noi contiamo i giorni che mancano. Mancano pochi giorni, fratelli."];
function rtChat2(){const U=rtUsers();if(U.length<4)return;const r=Math.random();
  if(r<.16){const p=alRand(U);const poi=alRand(AL_P.filter(x=>alZoneH(p.luogo||"Cordone",x.z)<=3&&!alCtl(x.id)[0]));if(!poi)return;rtPost(p,`Qualcosa a ${poi.n}`,alRand(RT_ANOM).replace("{p}",`${poi.n} (${poi.z})`),"anomalie",{kind:"anom",poi:poi.id});return;}
  if(r<.28){const p=alRand(U.filter(q=>{const a=anOf(q.id);return anHas(a,"avido")||anHas(a,"cinico")||anHas(a,"curioso");}))||alRand(U);const q=1000*(2+Math.floor(Math.random()*6));
    rtPost(p,"Affari",alRand([`Ho una pista su un deposito dell'esercito mai aperto. Mi serve un socio che metta ${fmtR(q)} per l'attrezzatura. Si divide a metà. Il doppio, se va bene.`,`Cerco un investitore. ${fmtR(q)} per un carico di medicine dal Cordone al nord. Al nord le medicine valgono tre volte. Si divide.`,`Un artefatto raro, già localizzato. Servono ${fmtR(q)} per la tuta giusta. Chi entra con me prende un terzo.`]),"affari",{kind:"affare",q});return;}
  if(r<.38){const p=alRand(U);const poi=alRand(AL_P.filter(x=>["rovine","rifugio","fattoria","deposito"].includes(AL_T[x.t])));if(!poi)return;const ogg=alRand(["l'orologio di mio padre","una croce d'argento","il mio diario","la fede di mio fratello","una scatola di latta con le lettere di casa"]);
    rtPost(p,"Ho perso una cosa",`Ho perso ${ogg} a ${poi.n} (${poi.z}), scappando. Non vale niente per voi. Per me vale tutto. Pago chi me lo riporta.`,"aiuto",{kind:"perso",poi:poi.id,ogg});return;}
  if(r<.48){const p=alRand(U);rtPost(p,"Un sogno",alRand(RT_SOGNO),"sogni",{kind:"sogno"});return;}
  if(r<.56){rtPost("anonimo","Confessione",alRand(RT_CONF),"confessioni",{kind:"conf",chi:(alRand(U)||{}).id});return;}
  if(r<.64){rtPost("un fratello del Monolite","La Voce",alRand(RT_PRED),"fazioni",{kind:"pred"});return;}
  if(r<.74&&(+S.nomeRep||0)>=2){const p=alRand(U.filter(q=>anHas(anOf(q.id),"orgoglioso")||anHas(anOf(q.id),"collerico")||anHas(anOf(q.id),"mitomane")))||alRand(U);
    rtPost(p,`Sfida a ${S.pg.sopr||"te"}`,alRand([`Tutti parlano di ${S.pg.sopr||"questo"}. Io dico che è un pallone gonfiato. Se ha coraggio, ci vediamo all'Arena. Mille rubli a chi resta in piedi.`,`${S.pg.sopr||"Tu"}: dicono che sei bravo. Io dico di no. Dimostralo. Arena del Bar, quando vuoi. Se non vieni, lo sapranno tutti.`]),"te",{kind:"sfida",pid:p.id});return;}
  if(r<.84){const p=alRand(U);const z=alRand(["Agroprom","Valle Oscura","Yantar","Magazzini dell'esercito","Radar","Zaton","Janiv e Jupiter"]);rtPost(p,"Mappe",`Vendo la mappa aggiornata di ${z}: chi tiene cosa, dove sono le tane, dove passare. Fresca di ieri. Prezzo d'amico.`,"mercato",{kind:"mappa",z});return;}
  if(r<.92){const p=alRand(U);const q=500*(1+Math.floor(Math.random()*4));rtPost(p,"Scommesse",alRand([`Si accettano scommesse: prossima Emissione entro tre giorni? Io dico di sì. Quote alla pari, puntata ${fmtR(q)}.`,`Scommessa: la Libertà riprende un punto ai Magazzini entro una settimana. Io dico di no. ${fmtR(q)} a chi vuole il contrario.`]),"affari",{kind:"scom",q,dal:S.clock.data});return;}
  const p=alRand(U);const poi=alRand(AL_P.filter(x=>alZoneH(p.luogo||"Cordone",x.z)<=4));if(!poi)return;rtPost(p,"Scorta",`Devo arrivare a ${poi.n} (${poi.z}) con un carico. Da solo non ci arrivo. Pago bene chi mi accompagna e non fa domande.`,"lavoro",{kind:"scorta",poi:poi.id,pid:p.id});}
